fn text_delta_event(seq: u64, delta: &str) -> String {
    format!(
        r#"{{"type":"response.output_text.delta","sequence_number":{seq},"item_id":"msg_01","output_index":0,"content_index":0,"delta":"{delta}"}}"#
    )
