/// because the Responses API ends the stream on the terminal event (SMA-585).
fn sse(events: &[String]) -> String {
    let mut out = String::new();
    for event in events {
        out.push_str("data: ");
        out.push_str(event);
        out.push_str("\n\n");
    }
    out
}

